INSERT INTO `contents` (`id`, `source_type`, `content_type`, `source_id`, `slug`, `title`, `english_title`, `summary`, `canonical_url`, `language`, `country`, `origin`, `nationality`, `field`, `year`, `image_url`, `image_urls`, `verification_status`, `content_hash`, `source_updated_at`, `indexed_at`, `created_at`, `updated_at`) VALUES
('doc-card-1', 'card', 'theory', 'card-1', 'mc-001', 'تعیین و برجسته‌سازی دستور کار', 'Agenda-Setting Theory', 'رسانه‌ها لزوماً به مخاطبان دیکته نمی‌کنند که «چگونه فکر کنند»، اما با موفقیتی چشمگیر تعیین می‌کنند که «درباره چه مسائلی فکر کنند». اولویت‌بندی موضوعات در خروجی رسانه‌ها (Media Agenda) از طریق انتقال برجستگی به اولویت‌های ذهنی و گفتمانی شهروندان (Public Agenda) منتقل می‌شود و …', 'https://resaname.ir/cards/card-1', 'fa', 'آمریکایی', 'international', NULL, NULL, NULL, NULL, NULL, 'verified', 'd06b835fb168eb8299e9380c8e3e7ae02b4dc9e4b0924cfe39165bd7fa484c40', '2026-10-14 15:42:11', '2026-11-09 10:38:23', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-10', 'card', 'effect', 'card-10', 'mc-010', 'اثر شخص سوم', 'Third-Person Effect', 'افراد تمایل دارند اثر پیام‌های رسانه‌ای (به‌ویژه پیام‌های منفی و اقناعی) را بر «دیگران» بیش از اثر آن بر «خودشان» برآورد کنند (مؤلفه ادراکی). این ادراک نابرابر می‌تواند به کنش‌هایی مانند حمایت از سانسور یا مقررات‌گذاری منجر شود (مؤلفه رفتاری).', 'https://resaname.ir/cards/card-10', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '8eaf460420615748ce13cecb06126317cbc62a5a11e94b5cdf603ca059b79653', '2026-10-14 01:43:01', '2026-11-09 10:38:23', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-100', 'card', 'concept', 'card-100', 'mc-100', 'جوامع تصوری', 'Imagined Communities', 'ملت جامعه‌ای «تصوری» است، چون اعضا هرگز همه یکدیگر را نمی‌شناسند ولی تصویر هم‌پیوندی در ذهن دارند. اندرسون «سرمایه‌داری چاپی» را عامل مهم شکل‌گیری آن می‌داند: روزنامه و رمان به خوانندگان پراکنده حس زمان همگون و هم‌زمانی می‌دادند.', 'https://resaname.ir/cards/card-100', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '6ad1b8d643604b340807b95ffb0b02508cc58ed0c9749047e8123b8fb01bc8f9', '2026-10-14 01:36:04', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-101', 'card', 'effect', 'card-101', 'mc-101', 'اثر رسانه خصمانه', 'Hostile Media Effect', 'افراد با نگرش قوی و درگیری بالا درباره موضوعی، یک پوشش خبری یکسان را علیه موضع خود ارزیابی می‌کنند؛ طرفداران دو سوی مناقشه هر دو آن را سوگیرانه می‌بینند. توضیح‌های رایج شامل ادراک گزینشی و دسته‌بندی گزینشی است.', 'https://resaname.ir/cards/card-101', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '6488652f35b230a7ce6dfe291e303c931ef770052b47740384f8a5ec9eda6ac8', '2026-10-14 01:36:03', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-102', 'card', 'phenomenon', 'card-102', 'mc-102', 'تعامل پاراسوشیال', 'Parasocial Interaction', 'هورتن و ول باس نشان دادند مخاطب می‌تواند با شخصیت رسانه‌ای (مجری، سلبریتی، اینفلوئنسر) رابطه‌ای به‌ظاهر رودررو و صمیمی شکل دهد، هرچند یک‌سویه است. تکرار مواجهه و شیوه‌ی خطاب مستقیم این احساس آشنایی و صمیمیت را تقویت می‌کند.', 'https://resaname.ir/cards/card-102', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', 'f071fbac3833b721d3c78979edb529a3d9922009a47f14c29656e202ed93a632', '2026-10-14 01:36:04', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-103', 'card', 'theory', 'card-103', 'mc-103', 'نظریه مقایسه اجتماعی', 'Social Comparison Theory', 'فستینگر می‌گوید افراد برای ارزیابی توانایی‌ها و نگرش‌های خود، خود را با دیگران مقایسه می‌کنند. در رسانه، مقایسه‌ی رو به بالا (با افراد برتر) و رو به پایین می‌تواند بر عزت‌نفس، خلق و تصویر بدن اثر بگذارد و اغلب به‌سمت بالایی صورت می‌گیرد.', 'https://resaname.ir/cards/card-103', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '10b237e3094c496177c9ce956787cbc34b7d352b2d0a1d69f0368ea0e97e1031', '2026-10-14 01:36:04', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-104', 'card', 'theory', 'card-104', 'mc-104', 'نظریه مدیریت خلق', 'Mood Management Theory', 'افراد، معمولاً ناخودآگاه، محتوای رسانه‌ای را برای حفظ یا بهبود حالت عاطفی خود انتخاب می‌کنند؛ مثلاً فرد خسته یا برانگیخته محتوای آرام‌بخش یا سرگرم‌کننده برمی‌گزیند. انتخاب بر اساس ویژگی‌هایی مثل برانگیختگی و ارزش هدونیک محتواست.', 'https://resaname.ir/cards/card-104', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '9f2639f935435e454299280e679faa885293a30b9c211a8f606bff7df8d1e95e', '2026-10-14 01:36:02', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-105', 'card', 'theory', 'card-105', 'mc-105', 'انتقال برانگیختگی', 'Excitation Transfer Theory', 'برانگیختگی فیزیولوژیک ناشی از یک محرک می‌تواند به‌کندی فروکش کند و بر واکنش عاطفی به محرک بعدی بیفزاید، به‌ویژه اگر فرد منبع برانگیختگی را اشتباه نسبت دهد. بنابراین محتوای قبلی می‌تواند شدت پاسخ به محتوای بعدی را تغییر دهد.', 'https://resaname.ir/cards/card-105', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '68b4e4eb7014d5da31e9cd1a14f01736677910d08f2d8205234e0e10c5edcb74', '2026-10-14 01:36:04', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-106', 'card', 'model', 'card-106', 'mc-106', 'مدل عمومی پرخاشگری', 'General Aggression Model', 'عوامل فردی و موقعیتی (از جمله مواجهه با خشونت رسانه‌ای) از طریق شناخت، عواطف و برانگیختگی بر ارزیابی و تصمیم تأثیر می‌گذارند و می‌توانند احتمال پرخاشگری را افزایش دهند. مواجهه مکرر می‌تواند از طریق یادگیری، دانش‌ساخت‌های پرخاشگرانه را تقویت کند.', 'https://resaname.ir/cards/card-106', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '5777160a936bfbb1df284eeb332a62de0976237a75417a5be6fbb00b0dc1c6a6', '2026-10-14 01:36:04', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-107', 'card', 'model', 'card-107', 'mc-107', 'مدل ظرفیت محدود پردازش پیام‌های رسانه‌ای', 'Limited Capacity Model of Motivated Mediated Message Processing', 'ظرفیت شناختی انسان محدود است و پردازش پیام شامل رمزگذاری، ذخیره و بازیابی است که از منابع مشترک بهره می‌گیرند. اگر پیام بیش از حد منابع را مصرف کند (بار شناختی)، کیفیت یادآوری افت می‌کند. سیستم‌های انگیزشی (رویکرد و اجتناب) تخصیص منابع را هدایت می‌کنند.', 'https://resaname.ir/cards/card-107', 'fa', 'بریتانیایی / جامائیکایی', 'international', NULL, NULL, NULL, NULL, NULL, 'verified', '3e82118bb25549f85a74f6fa2c9313a0423943196658227b6e9b829013a2048a', '2026-10-14 01:36:04', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-108', 'card', 'model', 'card-108', 'mc-108', 'مدل حساسیت دیفرانسیلی به اثرات رسانه', 'Differential Susceptibility to Media Effects Model', 'اثر رسانه بر همه یکسان نیست. سه دسته متغیر (تفاوت‌های فردی در شرایط رشدی و فردی، اجتماعی و بافتی) از راه انتخاب رسانه، پاسخ‌های شناختی، هیجانی و برانگیختگی بر اثر رسانه اثر می‌گذارند. اثر نیز می‌تواند دوسویه باشد: مصرف رسانه خود ویژگی‌های فرد را تغییر می‌دهد.', 'https://resaname.ir/cards/card-108', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', 'c3179e77e0d6694119708e1b0e95ffc49e920c2b55614537ce923411b397487b', '2026-10-14 01:36:04', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-109', 'card', 'effect', 'card-109', 'mc-109', 'اثر خواب‌آلود', 'Sleeper Effect', 'پیامی که همراه با نشانه‌ی کم‌اعتبار ارائه شده است ممکن است در لحظه‌ی دریافت تأثیر کمی داشته باشد، اما پس از گذشت زمان، به‌دلیل جداشدن پیام از منبع یا نشانه‌ی بدنام‌کننده در حافظه، اثر متقاعدسازی آن افزایش یابد.', 'https://resaname.ir/cards/card-109', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '2ddfb61b673df9f0dc54535da8abd07a2bfcd16647224e2bd26005d58fe00ab5', '2026-10-14 01:36:01', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-11', 'card', 'hypothesis', 'card-11', 'mc-011', 'فرضیه شکاف دانش', 'Knowledge Gap Hypothesis', 'با افزایش انتشار اطلاعات رسانه‌ای در یک نظام اجتماعی، گروه‌های برخوردار از پایگاه اجتماعی-اقتصادی (SES) بالاتر، اطلاعات را با سرعتی بیشتر از گروه‌های کم‌برخوردار جذب و هضم می‌کنند. در نتیجه، توزیع نامتوازن اطلاعات باعث می‌شود شکاف آگاهی میان این دو گروه در طول زمان افزایش یابد …', 'https://resaname.ir/cards/card-11', 'fa', 'آمریکایی', 'international', NULL, NULL, NULL, NULL, NULL, 'verified', 'a80cd0e91a8dea241f71776900c35277c20f0ea507425ad5a67c98f2eb12fec1', '2026-10-14 14:55:37', '2026-11-09 10:38:23', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-110', 'card', 'effect', 'card-110', 'mc-110', 'اثر حقیقت‌نمایی (تکرار)', 'Illusory Truth Effect', 'هاشر و همکاران نشان دادند تکرار یک گزاره باعث می‌شود پردازش آن روان‌تر و آشناتر شود و در نتیجه درست‌تر به نظر برسد، حتی اگر نادرست باشد. این اثر حتی وقتی فرد دانش درست را دارد نیز می‌تواند رخ دهد و پخش مداوم اطلاعات نادرست را تقویت می‌کند.', 'https://resaname.ir/cards/card-110', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '85e5218ebf234282a3765af1bcde1149a4aa42bba010e3bfa9cbf1d81bf42217', '2026-10-14 01:36:04', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-111', 'card', 'concept', 'card-111', 'mc-111', 'امکان‌دهی‌ها', 'Affordances', 'ویژگی‌های یک فناوری، کنش‌هایی را که برای کاربر ممکن یا دشوار می‌شوند تعیین می‌کند، اما این امکان‌ها هنگام استفاده و در بافت اجتماعی فعال می‌شوند. امکان‌دهی رابطه‌ای است میان ویژگی‌های ابژه و توانایی‌ها و اهداف کاربر، نه صفت ذاتی فناوری.', 'https://resaname.ir/cards/card-111', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', 'a1b7815c570b52bc8cce70ce723537035e9513522983cfde0deed88deb3d8f23', '2026-10-14 01:36:04', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-112', 'card', 'phenomenon', 'card-112', 'mc-112', 'حباب فیلتر', 'Filter Bubble', 'موتورهای جست‌وجو و پلتفرم‌ها با یادگیری ترجیحات کاربر، محتوای همسو با رفتار گذشته او را بیشتر نشان می‌دهند. نتیجه، کاهش مواجهه با دیدگاه‌های متفاوت و جهان اطلاعاتی متفاوت برای هر کاربر است که کاربر معمولاً از آن آگاه نیست.', 'https://resaname.ir/cards/card-112', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', 'cf2ea3a3d958c6a3199c68fea13d0291b87664e8635b26f351da083c32cad940', '2026-10-14 01:36:02', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-113', 'card', 'phenomenon', 'card-113', 'mc-113', 'اتاق پژواک', 'Echo Chamber', 'در شبکه‌های گفتگو، افراد با هم‌فکران تعامل بیشتری دارند و دیدگاه‌های مخالف کمتر به آنان می‌رسد. این ساختار، باورهای موجود را تقویت و قطبی‌شدن گروهی را افزایش می‌دهد. سانشتاین نگران تضعیف گفت‌وگوی دموکراتیک و تعامل با «گوناگونی» دیدگاه‌هاست.', 'https://resaname.ir/cards/card-113', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', 'd66bd7797fba5cf32835dfb08b0b79995b5cab1f626163c0019f84b17ce1debd', '2026-10-14 01:36:02', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-114', 'card', 'phenomenon', 'card-114', 'mc-114', 'فرهنگ مشارکتی', 'Participatory Culture', 'مصرف‌کنندگان رسانه همزمان تولیدکننده و توزیع‌کننده محتوا می‌شوند. این فرهنگ حول اجتماع‌های غیررسمی، اشتراک دانش و مهارت‌های جمعی شکل می‌گیرد. مشارکت تنها دسترسی به فناوری نیست، بلکه شامل مهارت‌های اجتماعی و نهادینه‌شدن ارزش‌های همکاری است.', 'https://resaname.ir/cards/card-114', 'fa', 'آمریکایی', 'international', NULL, NULL, NULL, NULL, NULL, 'verified', 'aca4d2553b7e27faf612f5084bc23c2fcecccf1cba83cfc4aec527e74e1f5bb0', '2026-10-14 01:36:02', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-115', 'card', 'phenomenon', 'card-115', 'mc-115', 'فردگرایی شبکه‌ای', 'Networked Individualism', 'در جامعه شبکه‌ای، افراد کمتر در گروه‌های محلی و بسته عضویت دارند و بیشتر از طریق شبکه‌های شخصی و چندمرکزی زندگی می‌کنند. فناوری‌های ارتباطی امکان حفظ پیوندهای ضعیف و قوی را در فواصل زیاد می‌دهند و فرد مرکز شبکه شخصی خود می‌شود.', 'https://resaname.ir/cards/card-115', 'fa', 'اسپانیایی', 'international', NULL, NULL, NULL, NULL, NULL, 'verified', 'ae577ed6c4f8f025bdab2f59f694e5946f2bfcbaa1b566c4be6359245be942a6', '2026-10-14 01:36:02', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-116', 'card', 'phenomenon', 'card-116', 'mc-116', 'فروپاشی بافتار', 'Context Collapse', 'در رسانه‌های اجتماعی، مخاطبان گوناگون (خانواده، همکاران، غریبه‌ها) در یک فضای واحد جمع می‌شوند و کاربر نمی‌تواند پیام خود را برای هر گروه تنظیم کند. این «فروپاشی» منجر به خودسانسوری، تنظیم دقیق‌تر پیام یا تغییر در هنجارهای ارتباط می‌شود.', 'https://resaname.ir/cards/card-116', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', 'a33c7a34d83bf874c75ef76acb649187eff1e05153fe9ff59cf8b74aa182682c', '2026-10-14 01:36:01', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-117', 'card', 'concept', 'card-117', 'mc-117', 'جامعه پلتفرمی', 'Platform Society', 'پلتفرم‌های دیجیتال (جست‌وجو، شبکه‌های اجتماعی، بازارها، تاکسی‌های آنلاین) زیرساخت‌هایی هستند که تعامل اجتماعی و اقتصادی را میانجی‌گری و از طریق داده و الگوریتم سازمان‌دهی می‌کنند. نهادهای عمومی و خصوصی باید خود را با منطق پلتفرمی هماهنگ کنند.', 'https://resaname.ir/cards/card-117', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '33649a73b0f661d22c8d4b289a6fa9bca7b6bbaa1859f2251296e7b816933cc3', '2026-10-14 01:36:03', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-118', 'card', 'concept', 'card-118', 'mc-118', 'سرمایه‌داری نظارتی', 'Surveillance Capitalism', 'شرکت‌های فناوری، داده‌های رفتاری کاربران را به‌عنوان «مواد خام» استخراج می‌کنند و از آن برای پیش‌بینی و تغییر رفتار در بازارهای آینده بهره می‌برند. منطق اصلی آن بر «مازاد رفتاری» و کسب سود از پیش‌بینی رفتار است، نه صرفاً ارائه خدمت.', 'https://resaname.ir/cards/card-118', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '04b5efb3d62c73d8d19771d820fcf49957d21332aaaca15615b37f798de995c2', '2026-10-14 01:36:02', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-119', 'card', 'concept', 'card-119', 'mc-119', 'تخیل الگوریتمی', 'The Algorithmic Imaginary', 'کاربران تصوراتی درباره نحوه کار الگوریتم‌ها می‌سازند و بر اساس آن رفتار می‌کنند، حتی اگر این تصورات دقیق نباشند. این «تخیل» نقش مهمی در شکل‌دادن به عادت‌های استفاده، برداشت از فرهنگ عمومی و احساس قدرت یا ناتوانی کاربر دارد.', 'https://resaname.ir/cards/card-119', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '58840f158aedb94f27bd776ef36b4b3c4ea6d61a16ac3102c40322d95fac8460', '2026-10-14 01:36:04', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-12', 'card', 'theory', 'card-12', 'mc-012', 'جریان دو مرحله‌ای ارتباطات', 'Two-Step Flow of Communication', 'پیام‌های رسانه‌ای به طور مستقیم، همگن و یکنواخت بر توده‌های منفرد اثر نمی‌گذارند. ایده‌ها ابتدا از رسانه‌های جمعی به «رهبران افکار» (Opinion Leaders) می‌رسند و سپس از طریق کانال‌های ارتباطی بین‌فردی، شبکه‌های دوستی و پیوندهای گروهی به بخش‌های کمتر فعال جامعه منتقل می‌شوند. نفوذ …', 'https://resaname.ir/cards/card-12', 'fa', 'آمریکایی / اسرائیلی', 'international', NULL, NULL, NULL, NULL, NULL, 'verified', 'fd4d7ed672828b01bdccea926941a90aaeb49e27e1c1ad2718f94e6c2b8c7ac5', '2026-10-14 14:55:19', '2026-11-09 10:38:23', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-120', 'card', 'phenomenon', 'card-120', 'mc-120', 'شکاف دیجیتال', 'Digital Divide', 'نابرابری در دسترسی به فناوری اطلاعات و ارتباطات، نخستین سطح شکاف است. با گسترش دسترسی، شکاف دوم (مهارت، استفاده و کیفیت بهره‌برداری) و شکاف سوم (پیامدهای کیفی برای فرصت‌های اجتماعی و اقتصادی) اهمیت می‌یابد. این شکاف‌ها با درآمد، تحصیلات، جنسیت و منطقه همبسته‌اند.', 'https://resaname.ir/cards/card-120', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', 'e4785ddfbb45941cf7eac81b9a40ecd3abd8c64e49395d0069bcbf344158ccf1', '2026-10-14 01:36:03', '2026-11-09 10:38:24', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-121', 'card', 'model', 'card-121', 'mc-121', 'مدل‌های چهارگانه روابط عمومی', 'Four Models of Public Relations', 'گرونیگ و هانت چهار الگوی روابط عمومی را طبقه‌بندی کردند: انتشاراتی (Press Agentry)، اطلاع‌رسانی عمومی (Public Information)، دوطرفه نامتقارن (Two-Way Asymmetrical) و دوطرفه متقارن (Two-Way Symmetrical). الگوهای نخست بیشتر بر انتقال پیام یک‌طرفه تمرکز دارند؛ الگوهای دوطرفه بر …', 'https://resaname.ir/cards/card-121', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '9455299959d0ac27547ab45e9b2c472847a469b9b75c89724ffb566212ce248b', '2026-10-14 01:36:01', '2026-11-09 10:38:25', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-122', 'card', 'theory', 'card-122', 'mc-122', 'نظریه ارتباطات بحران وضعیتی', 'Situational Crisis Communication Theory', 'نوع بحران میزان مسئولیت درک‌شده سازمان و در نتیجه تهدید سمعه را تعیین می‌کند. کومز راهبردهای پاسخ را در چهار دسته قرار داد: انکار (Denial)، کاهش‌دهی (Diminishment)، بازسازی (Rebuilding: جبران و عذرخواهی) و تقویت (Bolstering: یادآوری نکات مثبت پیشین). انتخاب راهبرد باید با میزان …', 'https://resaname.ir/cards/card-122', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '4d72632eae9cd27dcfb960dd0f94fccc117e198db241bb520ae31d4a0f45ca5e', '2026-10-14 01:36:04', '2026-11-09 10:38:25', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-123', 'card', 'framework', 'card-123', 'mc-123', 'چارچوب تقویت اجتماعی ریسک', 'Social Amplification of Risk Framework', 'خطر واقعی و خطر درک‌شده همیشه یکی نیستند. رسانه‌ها، نهادها و شبکه‌های اجتماعی از طریق گزینش، قاب‌بندی و تکرار پیام‌ها می‌توانند ریسک را تقویت یا تضعیف کنند. این تقویت به رفتار و پیامدهای اجتماعی (مانند اقتصادی یا سیاسی) نیز منتقل می‌شود.', 'https://resaname.ir/cards/card-123', 'fa', 'کانادایی / آمریکایی', 'international', NULL, NULL, NULL, NULL, NULL, 'verified', 'eb3bc007f2ea5ba753dafaf68ebc59969c557a5ad884700f432d3e02d683a967', '2026-10-14 01:36:04', '2026-11-09 10:38:25', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-124', 'card', 'concept', 'card-124', 'mc-124', 'هویت و تصویر سازمانی', 'Organizational Identity and Image', 'هویت سازمانی آن چیزی است که اعضا درباره‌ی سازمان باور دارند؛ تصویر سازمانی آن چیزی است که بیرونیان درک می‌کنند. وقتی میان این دو شکاف پدید می‌آید، سازمان برای ترمیم آن راهبردهای ارتباطی و رفتاری اتخاذ می‌کند. این فرایند بر روحیه کارکنان و جذب استعداد نیز اثر دارد.', 'https://resaname.ir/cards/card-124', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', 'f44c107fbde07ad2e718de1da1f8dc31c3eb65776fd561becea9c54eac1e21f4', '2026-10-14 01:36:04', '2026-11-09 10:38:25', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-125', 'card', 'theory', 'card-125', 'mc-125', 'نظریه وضعیت جمهورها', 'Situational Theory of Publics', 'جمهور یک توده‌ی یکنواخت نیست. گرونیگ سه متغیر را برای توضیح رفتار ارتباطی جمهورها معرفی کرد: درک مسئله (Problem Recognition)، درگیری (Level of Involvement) و درک محدودیت (Constraint Recognition). بر این اساس، جمهورها به سه دسته‌ی فعال (Active)، آگاه (Aware) و غیرفعال/نهفته …', 'https://resaname.ir/cards/card-125', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '54373be42b03317f0ad178db75cd1206b5b084f5c65c597ef56d724b69cdd383', '2026-10-14 01:36:04', '2026-11-09 10:38:25', '2026-11-10 02:01:31', '2026-11-10 02:01:31'),
('doc-card-126', 'card', 'framework', 'card-126', 'mc-126', 'قاب‌بندی سود و زیان در پیام‌رسانی', 'Gain vs. Loss Framing in Messaging', 'پیام‌ها را می‌توان بر «دستاوردها» یا «زیان‌ها» قاب‌بندی کرد. نظریه چشم‌انداز نشان می‌دهد افراد در برابر زیان حساس‌ترند تا در برابر سود متعادل. بر این پایه، در موقعیت‌های تشخیص‌یافته (مانند غربالگری پزشکی)، قاب زیان ممکن است اثر بیشتری داشته باشد؛ در رفتارهای پیشگیرانه، قاب …', 'https://resaname.ir/cards/card-126', 'fa', 'آمریکایی', 'international', NULL, NULL, NULL, NULL, NULL, 'verified', '2ab5a3d8885fe12a839b9ccd989571428ffe648e3b21a1686d84e06af18e6816', '2026-10-14 01:36:04', '2026-11-09 10:38:25', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-127', 'card', 'concept', 'card-127', 'mc-127', 'مدیریت سمعه شرکتی', 'Corporate Reputation Management', 'سمعه مجموعه‌ای از ادراکات ذی‌نفعان (سرمایه‌گذاران، کارکنان، مشتریان، رسانه) درباره‌ی یک سازمان است. سمعه‌ی قوی می‌تواند به جذب استعداد، اعتماد مشتری و دسترسی به سرمایه کمک کند. مدیریت سمعه به رفتار ثابت، شفافیت ارتباطی و شنیدن ذی‌نفعان نیازمند است.', 'https://resaname.ir/cards/card-127', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', '8557300c0376eab1b44a10c434a566f58146082d22783b5d63fe401e974e9824', '2026-10-14 01:36:04', '2026-11-09 10:38:25', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
('doc-card-128', 'card', 'framework', 'card-128', 'mc-128', 'ارتباطات مسئولیت اجتماعی شرکتی', 'CSR Communication', 'کرول مسئولیت شرکت را در چهار لایه‌ی اقتصادی، قانونی، اخلاقی و بشردوستانه سازمان‌دهی کرد. ارتباطات CSR این ادعاها را به ذی‌نفعان منتقل می‌کند. اعتبار این ارتباطات به همخوانی ادعا با عمل و شفافیت گزارش‌دهی بستگی دارد؛ در غیر این صورت، خطر «سبزشویی» (Greenwashing) وجود دارد.', 'https://resaname.ir/cards/card-128', 'fa', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'verified', 'ef8824872c52f671ad33061f51cf3170e98dfff88a602a2854df632b5e861f9a', '2026-10-14 01:00:20', '2026-11-09 10:38:25', '2026-11-10 02:01:31', '2026-11-10 03:42:49'),
